export function cantileverPeriod(height,massPerMetre,effectiveEI){
 if(![height,massPerMetre,effectiveEI].every(v=>Number.isFinite(v)&&v>0))return null;
 // First mode of a uniform fixed-base Euler–Bernoulli cantilever.
 return 2*Math.PI/(1.875104068711961**2)*height**2*Math.sqrt(massPerMetre/effectiveEI);
}
export function quarterWavePeriod(depth,velocity){return Number.isFinite(depth)&&Number.isFinite(velocity)&&depth>0&&velocity>0?4*depth/velocity:null}
